    "stem": "A 19-year-old man is admitted to the general observation ward of a rural health center in Balochistan with clinical findings indicative of Forensic Medical Examination of Blunt Force Trauma and Medicolegal Report Writing. Clinical examination and investigative review confirm meticulous documentation of contusions, abrasions, and lacerations with forensic injury certification. Vitals reveal blood pressure of 124/84 mm Hg, heart rate of 70/min, respiratory rate of 18/min, and temperature of 37.6C (98.1F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of forensic medical examination of blunt force trauma and medicolegal report writing. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
